func renderGraph(jobs []*Job, level map[string]int, format string) []byte {
	inSet := make(map[string]bool, len(jobs))
	for _, job := range jobs {
		inSet[job.Name] = true
	}

	var edges []graphEdge
	for _, job := range jobs {
		for _, dep := range job.Deps {
			if inSet[dep] {
				edges = append(edges, graphEdge{dep: dep, name: job.Name})
			}
		}
	}

	switch format {
	case "dot":
		return renderDot(jobs, level, edges)
	case "mermaid":
		return renderMermaid(jobs, edges)
	}
	return nil
}

func renderDot(jobs []*Job, level map[string]int, edges []graphEdge) []byte {
	var b strings.Builder
	b.WriteString("digraph jobforge {\n")
	b.WriteString("\trankdir=LR;\n")
	for _, job := range jobs {
		b.WriteString("\t\"")
		b.WriteString(dotQuote(job.Name))
		b.WriteString("\" [level=\"")
		b.WriteString(strconv.Itoa(level[job.Name]))
		b.WriteString("\",workdir=\"")
		b.WriteString(dotQuote(job.Workdir))
		b.WriteString("\"];\n")
	}
	for _, e := range edges {
		b.WriteString("\t\"")
		b.WriteString(dotQuote(e.dep))
		b.WriteString("\" -> \"")
		b.WriteString(dotQuote(e.name))
		b.WriteString("\";\n")
	}
	b.WriteString("}\n")
	return []byte(b.String())
}

func renderMermaid(jobs []*Job, edges []graphEdge) []byte {
	var b strings.Builder
	b.WriteString("graph LR\n")
	b.WriteString("\t%% nodes=")
	b.WriteString(strconv.Itoa(len(jobs)))
	b.WriteString(" edges=")
	b.WriteString(strconv.Itoa(len(edges)))
	b.WriteString("\n")
	for _, job := range jobs {
		b.WriteString("\t")
		b.WriteString(mermaidID(job.Name))
		b.WriteString("[\"")
		b.WriteString(mermaidLabel(job.Name))
		b.WriteString("\"]\n")
	}
	for _, e := range edges {
		b.WriteString("\t")
		b.WriteString(mermaidID(e.dep))
		b.WriteString(" --> ")
		b.WriteString(mermaidID(e.name))
		b.WriteString("\n")
	}
	return []byte(b.String())
}

func dotQuote(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}

func mermaidID(name string) string {
	var b strings.Builder
	for i := 0; i < len(name); i++ {
		c := name[i]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' {
			b.WriteByte(c)
		} else {
			b.WriteByte('_')
		}
	}
	return b.String()
}

func mermaidLabel(name string) string {
	var b strings.Builder
	for i := 0; i < len(name); i++ {
		c := name[i]
		if c == '"' {
			b.WriteString("#quot;")
		} else {
			b.WriteByte(c)
		}
	}
	return b.String()
}
